{"id":"2395a3bd-bd8f-4e9f-8022-1fec4d6ee71c","inserted_at":"2026-07-08T23:53:52.63274+00:00","updated_at":"2026-07-08T23:53:52.63274+00:00","type":"sql","name":"Untitled query","description":"","content":{"sql":"-- Tenant \"borgo-test\" (piccolo comune, solo turismo)\r\nINSERT INTO tenants (id, display_name, slug, primary_color, secondary_color, city_name, region, center_lat, center_lng, default_zoom, status, features)\r\nVALUES ('borgo-test', 'Borgo Antico', 'borgo-antico', '#2E8B57', '#F5F5DC', 'Borgo Antico', 'Puglia', 40.5000, 17.8000, 14, 'active', '{\r\n    \"civic_module\": false,\r\n    \"gamification\": true,\r\n    \"events\": false,\r\n    \"community_challenges\": false,\r\n    \"ble_heatmap\": false,\r\n    \"premium_boost\": false\r\n}')\r\nON CONFLICT (id) DO UPDATE SET features = EXCLUDED.features;\r\n\r\nINSERT INTO tenant_localizations (tenant_id, locale, onboarding_title, onboarding_subtitle, onboarding_cta, points_name, points_name_plural, civic_module_name, events_tab_name, events_empty_state)\r\nVALUES ('borgo-test', 'it', 'Benvenuto nel Borgo', 'Scopri i segreti di un paese che vive nel tempo.', 'Inizia', 'Punti', 'Punti', 'Segnalazioni', 'Eventi', 'Nessun evento programmato')\r\nON CONFLICT (tenant_id, locale) DO UPDATE SET onboarding_title = EXCLUDED.onboarding_title;","content_id":"2395a3bd-bd8f-4e9f-8022-1fec4d6ee71c","schema_version":"1.0"},"visibility":"user","favorite":false,"project":{"id":27102476,"ref":"fsuolbwsvpgiglwcaffh","name":"loto.hub","base_project_id":null},"owner":{"id":10709404,"username":"lototaranto-alt"},"updated_by":{"id":10709404,"username":"lototaranto-alt"},"message":""}
